import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int count = input.nextInt();
        int limit = input.nextInt();
        int[] data = new int[count];
        for (int i = 0; i < count; i++) {
            data[i] = input.nextInt();
        }
        System.out.println(findMaxSegments(data, limit));
    }

    private static int findMaxSegments(int[] array, int maxBudget) {
        ArrayList<Integer> diffList = new ArrayList<>();
        int evenCounter = array[0] % 2 == 0 ? 1 : 0;
        int oddCounter = array[0] % 2 == 1 ? 1 : 0;
        int segments = 0;
        for (int i = 1; i < array.length; i++) {
            if (oddCounter == evenCounter && Math.abs(array[i] - array[i - 1]) <= maxBudget) {
                evenCounter = 0;
                oddCounter = 0;
                diffList.add(Math.abs(array[i] - array[i - 1]));
            }
            if (array[i] % 2 == 0) {
                evenCounter++;
            } else {
                oddCounter++;
            }
        }
        Collections.sort(diffList);
        for (int difference : diffList) {
            if (maxBudget < difference) {
                break;
            }
            segments++;
            maxBudget -= difference;
        }
        return segments;
    }
}
