#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int findMaxSegments(const std::vector<int>& array, int maxBudget) {
    std::vector<int> diffList;
    int evenCounter = (array[0] % 2 == 0) ? 1 : 0;
    int oddCounter = (array[0] % 2 == 1) ? 1 : 0;
    int segments = 0;
    for (size_t i = 1; i < array.size(); ++i) {
        if (oddCounter == evenCounter && std::abs(array[i] - array[i - 1]) <= maxBudget) {
            evenCounter = 0;
            oddCounter = 0;
            diffList.push_back(std::abs(array[i] - array[i - 1]));
        }
        if (array[i] % 2 == 0) {
            evenCounter++;
        } else {
            oddCounter++;
        }
    }
    std::sort(diffList.begin(), diffList.end());
    for (int difference : diffList) {
        if (maxBudget < difference) {
            break;
        }
        segments++;
        maxBudget -= difference;
    }
    return segments;
}

int main() {
    int count, limit;
    std::cin >> count >> limit;
    std::vector<int> data(count);
    for (int i = 0; i < count; ++i) {
        std::cin >> data[i];
    }
    std::cout << findMaxSegments(data, limit) << std::endl;
    return 0;
}
